import os

from dotenv import load_dotenv
from langchain_community.document_loaders import TextLoader
from langchain_text_splitters import CharacterTextSplitter
from langchain_ollama import OllamaEmbeddings
from langchain_openai import OpenAIEmbeddings
from langchain_pinecone import PineconeVectorStore

# pinecone = an excellent vector database which became viral
load_dotenv()

if __name__ == "__main__":
    print("Ingesting...")

    loader = TextLoader(r"C:\github_projects\claudia_langchain_projects\rag_gist\mediumblog1.txt", encoding="utf-8")
    document = loader.load()

    print("splitting...")

    # Overlapping data might be useful when we don't want to use context between chunks, not the case now.
    # The rule of thumb would be to read the chunked text, to make sense and to have a semantic value, if not, probably
    # the chunk size is too small, and we need to increase it, but if the chunk size is too big, we might have problems
    # with the context window of the model, so we need to find a balance between the two.

    text_splitter = CharacterTextSplitter(chunk_size=1000, chunk_overlap=0)
    # document is a list of documents, but we have only one document, so we need to split it into chunks
    texts = text_splitter.split_documents(document)

    # We receive some warnings: "Created a chunk of size 1180, which is longer than the specified 1000". This is because
    # we are splitting on "\n" which is not the exact science, we might get longer chunks, but again those values are
    # very small, compared to the context windows of the current LLMs which can be 32K, 100K, 1M tokens.
    print(f"created {len(texts)} chunks")

    # It creates an OpenAI client.
    # embeddings = OpenAIEmbeddings(openai_api_key=os.environ.get("OPENAI_API_KEY"))

    embeddings = OllamaEmbeddings(model="nomic-embed-text")
    print("ingesting...")

    # any langchain vector store has from_documents method, which takes a list of documents and an embeddings object,
    # and creates a vector store. Langchain is going to iterate through all of the chunks, embed them and store them in
    # vector store.  - we can do it by ourselves, but it's easier with Langchain if we want to switch between different
    # vector stores or different models, the changes are minimal, using the same interface.

    # ingesting documents into vector store, PineconeVectorStore it uses threads, async in order to run things
    # concurrently and to handle rate limits. It has a lot of boilerplate code for production usage.
    PineconeVectorStore.from_documents(
        texts, embeddings, index_name=os.environ["INDEX_NAME"]
    )

